export const getPaymentMethodCrudDeleteUrl = (salonId: ModelsSalonId,
    id: ModelsPaymentMethodId,) => {




  return `/api/v1/salons/${salonId}/payment-methods/${id}`
}

/**
 * 支払い方法を削除します。決済取引が指している支払い方法は削除できず、409を返します(使わなくなった支払い方法は isActive を false にします)。支払い方法がそのサロンのものでない場合は404を返します。
 * @summary Delete payment method
 */
export const paymentMethodCrudDelete = async (salonId: ModelsSalonId,
    id: ModelsPaymentMethodId, options?: RequestInit): Promise<paymentMethodCrudDeleteResponse> => {

  return customInstance<paymentMethodCrudDeleteResponse>(getPaymentMethodCrudDeleteUrl(salonId,id),
  {
    ...options,
    method: 'DELETE'


  }
);}





